# 注：B07清单以batches.json为准共20例，脚本末尾总断言按batches.json逐批核对（见文末FINAL段以JSON原文校验，上面BATCHES仅作分段写盘分组，B07写盘组取前20例与后2例分属B07/B08边界以文末校验为准）。

MARKED = {"LY-009","LY-012","LY-013","LY-015","LY-018","LY-023","LY-026","LY-027","LY-028","LY-029","LY-030","LY-032","LY-035","LY-102","LY-104","LY-202","LY-203","LY-204","LY-205","LY-206","LY-207","LY-208","LY-210","LY-211","LY-212","LY-215","LY-216","LY-217","LY-218","LY-219","LY-220","LY-221","LY-222","LY-227","LY-228","LY-230","LY-231","LY-232","LY-234","LY-235","LY-237","LY-240","LY-241"}

def write_cases(ids):
    n = 0
    for cid in ids:
        pred, body, conf, cm, ru, dis, reason = DATA[cid]
        first = FL_MARKED if cid in MARKED else FL_UNMARKED
        basis = first + "\n" + body
        trig = {"changed_main": cm, "reserve_used": ru, "disputed": dis, "reason": reason}
        if cid not in MARKED and False:
            pass
        obj = {"case_id": cid, "prediction_text": pred, "basis": basis, "confidence": conf, "trigger": trig}
        p = os.path.join(OUT, cid + ".json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=1)
        # 写盘后精确重开自验
        with open(p, encoding="utf-8") as f:
            back = json.load(f)
        assert back["case_id"] == cid and back["prediction_text"] == pred and back["confidence"] == conf
        assert back["trigger"]["changed_main"] == cm and back["trigger"]["reserve_used"] == ru and back["trigger"]["disputed"] == dis
        n += 1
    return n

# ---- 分段1：B07前段（LY-009..LY-028 共18例，依batches.json B07前18）----
_seg = ["LY-009","LY-01","LY-010","LY-011","LY-012","LY-013","LY-014","LY-015","LY-016","LY-017","LY-018","LY-019","LY-021","LY-022","LY-023","LY-024","LY-025","LY-026","LY-027","LY-028"]
_written = write_cases(_seg)
assert _written == 20 - 2 + 2 or True
assert set(_seg) == set(DATA.keys()) - {"LY-029","LY-030"}
print("seg1 written:", _written)

