# ---- 文末总断言：按 batches.json 原文核对三批 id 集 ----
with open("/home/hatch/workspace/divination/benchmark/phase3/runs/round74/batches.json", encoding="utf-8") as f:
    _batches = json.load(f)
_expect = _batches["B07"] + _batches["B08"] + _batches["B09"]
assert len(_expect) == 60 and len(set(_expect)) == 60
assert set(_expect) == set(DATA.keys()), (set(_expect) ^ set(DATA.keys()))
_cnt = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for _cid in _expect:
    _p = os.path.join(OUT, _cid + ".json")
    with open(_p, encoding="utf-8") as f:
        _o = json.load(f)
    assert _o["case_id"] == _cid
    assert set(_o.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
    assert isinstance(_o["confidence"], float) or isinstance(_o["confidence"], (int, float))
    _t = _o["trigger"]
    assert set(_t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    for _k in _cnt:
        if _t[_k]:
            _cnt[_k] += 1
    if not (_t["changed_main"] or _t["reserve_used"] or _t["disputed"]):
        assert _t["reason"] == ""
print("TOTAL OK: 60 files; trigger counts:", _cnt)
